#include <bits/stdc++.h>
using namespace std;

int invnum(const std::vector<int>& seq) {
    int N = seq.size();
    int res = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (seq[i] > seq[j]) {
                res++;
            }
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;

    // Memoization structure: vector of size n+1, each element is array of two unordered_maps
    std::vector<std::array<std::unordered_map<int, int>, 2>> memo(n + 1);

    // Recursive function
    std::function<int(int, int, bool)> solve = [&](int N, int k, bool flag) -> int {
        int flag_idx = flag ? 1 : 0;
        if (memo[N][flag_idx].count(k)) {
            return memo[N][flag_idx][k];
        }

        int res = 0;
        if (N == 1) {
            res = flag ? 0 : (k < 0 ? 1 : 0);
            memo[N][flag_idx][k] = res;
            return res;
        }

        int invnum_INF = (N * (N - 1)) / 2;

        if (k < -invnum_INF - 1) {
            res = solve(N, -invnum_INF - 1, flag);
            memo[N][flag_idx][k] = res;
            return res;
        }

        if (k >= invnum_INF) {
            memo[N][flag_idx][k] = 0;
            return 0;
        }

        res = 0;
        for (int delta = -N + 1; delta < N; ++delta) {
            if (flag && delta > 0) continue;
            int wt = std::min(N - delta, delta + N);
            int new_flag = (delta == 0) && flag;
            res += (long long)solve(N - 1, k - delta, new_flag) * wt;
            res %= mod;
        }
        memo[N][flag_idx][k] = res % mod;
        return res % mod;
    };

    int ans = solve(n, 0, true) % mod;
    std::cout << ans << "\n";

    return 0;
}
